const fMar = 0.1; // margin percent
const fDev = 1.725; // deviation noise scale
const fN1 = 0.0123;
const fN2 = 0.0936;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
  M = S * fMar;
  describe("lines from top (regular) to bottom (noise)");
}

function draw() {
  background(32);
  strokeWeight(1.5);
  stroke("rgba(64,160,192,0.5)");

  for (let x = width * fMar; x < width * (1 - fMar); x += 0.5) {
    const dx = (noise(x * fN1) - 0.5) * M * fDev;
    const dy = (noise(x * fN2 + TWO_PI) - 0.5) * M * fDev;
    line(x, M, x + dx, height - M + dy);
  }

  // noLoop() removed for animation
}
